// Block colour helpers: perceptual lookups over scripts/lib/data/block-colors.json
// (generated by scripts/dev/gen-block-colors.mjs; guide: references/building/palettes.md,
// tables: references/building/block-colors.md).
//
//   colorOf('stone')                         -> entry { id, side, top, lab, L, C, h, family, noise, ... }
//   nearest('#8a6a50')                       -> { id, dE, side, L } closest full building block
//   nearest('stone', { count: 3 })           -> 3 closest substitutes for stone (stone itself excluded)
//   ramp('calcite', 'blackstone', 7)         -> 7 block ids, smoothest perceptual ladder
//   sortByLightness(ids)                     -> lightest first
//   contrast('stone_bricks', 'spruce_planks')-> { dL, dE, reads }
//   paletteReport({ wall: 'x', roof: 'y' })  -> { value, hue, busy, warnings, ok }
//
// Everything is cached after the first call; only Node built-ins are used.

import fs from 'node:fs'

const DATA_URL = new URL('../data/block-colors.json', import.meta.url)
const MATERIALS_URL = new URL('../data/materials.json', import.meta.url)

// ---------------------------------------------------------------------------------------------
// Colour math (same formulas as the generator).
// ---------------------------------------------------------------------------------------------

const srgbToLinear = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4)

export function hexToRgb(hex) {
  const h = String(hex).replace(/^#/, '')
  if (!/^[0-9a-fA-F]{6}$/.test(h)) throw new Error(`invalid hex colour: ${hex}`)
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16))
}

export function rgbToLab([r, g, b]) {
  const R = srgbToLinear(r / 255)
  const G = srgbToLinear(g / 255)
  const B = srgbToLinear(b / 255)
  const X = (0.4124564 * R + 0.3575761 * G + 0.1804375 * B) / 0.95047
  const Y = 0.2126729 * R + 0.7151522 * G + 0.072175 * B
  const Z = (0.0193339 * R + 0.119192 * G + 0.9503041 * B) / 1.08883
  const f = (t) => (t > 216 / 24389 ? Math.cbrt(t) : (24389 / 27 * t + 16) / 116)
  const fx = f(X)
  const fy = f(Y)
  const fz = f(Z)
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)]
}

export const hexToLab = (hex) => rgbToLab(hexToRgb(hex))

export function deltaE(lab1, lab2) {
  const [L1, a1, b1] = lab1
  const [L2, a2, b2] = lab2
  const rad = Math.PI / 180
  const C1 = Math.hypot(a1, b1)
  const C2 = Math.hypot(a2, b2)
  const Cm7 = ((C1 + C2) / 2) ** 7
  const G = 0.5 * (1 - Math.sqrt(Cm7 / (Cm7 + 25 ** 7)))
  const a1p = (1 + G) * a1
  const a2p = (1 + G) * a2
  const C1p = Math.hypot(a1p, b1)
  const C2p = Math.hypot(a2p, b2)
  const h1p = C1p === 0 ? 0 : (Math.atan2(b1, a1p) / rad + 360) % 360
  const h2p = C2p === 0 ? 0 : (Math.atan2(b2, a2p) / rad + 360) % 360
  const dLp = L2 - L1
  const dCp = C2p - C1p
  let dhp = 0
  if (C1p * C2p !== 0) {
    dhp = h2p - h1p
    if (dhp > 180) dhp -= 360
    else if (dhp < -180) dhp += 360
  }
  const dHp = 2 * Math.sqrt(C1p * C2p) * Math.sin((dhp / 2) * rad)
  const Lpm = (L1 + L2) / 2
  const Cpm = (C1p + C2p) / 2
  let hpm = h1p + h2p
  if (C1p * C2p !== 0) {
    if (Math.abs(h1p - h2p) > 180) hpm = h1p + h2p < 360 ? (h1p + h2p + 360) / 2 : (h1p + h2p - 360) / 2
    else hpm = (h1p + h2p) / 2
  }
  const T = 1 - 0.17 * Math.cos((hpm - 30) * rad) + 0.24 * Math.cos(2 * hpm * rad)
    + 0.32 * Math.cos((3 * hpm + 6) * rad) - 0.2 * Math.cos((4 * hpm - 63) * rad)
  const dTheta = 30 * Math.exp(-(((hpm - 275) / 25) ** 2))
  const Cpm7 = Cpm ** 7
  const Rc = 2 * Math.sqrt(Cpm7 / (Cpm7 + 25 ** 7))
  const Sl = 1 + (0.015 * (Lpm - 50) ** 2) / Math.sqrt(20 + (Lpm - 50) ** 2)
  const Sc = 1 + 0.045 * Cpm
  const Sh = 1 + 0.015 * Cpm * T
  const Rt = -Math.sin(2 * dTheta * rad) * Rc
  return Math.sqrt((dLp / Sl) ** 2 + (dCp / Sc) ** 2 + (dHp / Sh) ** 2 + Rt * (dCp / Sc) * (dHp / Sh))
}

const lch = ([L, a, b]) => ({ L, C: Math.hypot(a, b), h: ((Math.atan2(b, a) * 180) / Math.PI + 360) % 360 })

// Colour family of a Lab colour (same rule as block-colors.md).
export function familyOf(lab) {
  const { L, C, h } = lch(lab)
  if (C < 10) return 'neutral'
  if (h >= 345 || h < 42) {
    if (L >= (h >= 345 ? 55 : 60)) return 'pink'
    return h >= 345 ? 'purple' : 'red'
  }
  if (h < 75) return L >= 66 ? 'yellow' : C >= 36 ? 'orange' : 'brown'
  if (h < 113) return C < 36 && L < 66 ? 'brown' : 'yellow'
  if (h < 160) return 'green'
  if (h < 225) return 'teal'
  if (h < 308) return 'blue'
  return 'purple'
}

// ---------------------------------------------------------------------------------------------
// Data, tags and caches.
// ---------------------------------------------------------------------------------------------

// Excluded from nearest()/ramp() unless named in `kinds` or `include`.
const TECHNICAL = new Set([
  'command_block', 'chain_command_block', 'repeating_command_block', 'structure_block', 'structure_void',
  'jigsaw', 'barrier', 'light', 'spawner', 'trial_spawner', 'vault', 'moving_piston', 'end_portal',
  'end_gateway', 'nether_portal', 'end_portal_frame', 'bubble_column', 'fire', 'soul_fire', 'frosted_ice',
  'piston_head', 'test_block', 'test_instance_block',
])
const FUNCTIONAL = new Set([
  'crafting_table', 'furnace', 'blast_furnace', 'smoker', 'dispenser', 'dropper', 'observer', 'piston',
  'sticky_piston', 'note_block', 'jukebox', 'bookshelf', 'chiseled_bookshelf', 'barrel', 'loom',
  'cartography_table', 'fletching_table', 'smithing_table', 'crafter', 'tnt', 'target', 'beehive', 'bee_nest',
  'lodestone', 'respawn_anchor', 'sculk_catalyst', 'redstone_lamp', 'pumpkin', 'carved_pumpkin',
  'jack_o_lantern', 'melon', 'copper_bulb', 'exposed_copper_bulb', 'weathered_copper_bulb', 'oxidized_copper_bulb',
  'enchanting_table', 'beacon', 'conduit', 'sculk_sensor', 'calibrated_sculk_sensor', 'sculk_shrieker',
])
const CREATIVE = new Set(['bedrock', 'reinforced_deepslate', 'budding_amethyst'])
const TERRAIN = new Set(['grass_block', 'mycelium', 'podzol', 'crimson_nylium', 'warped_nylium', 'dirt_path', 'farmland'])
const DEFAULT_EXCLUDED = ['technical', 'ore', 'glazed', 'alias', 'functional', 'emissive', 'live_coral', 'creative', 'approx']
const RAMP_EXCLUDED = [...DEFAULT_EXCLUDED, 'terrain', 'tinted']

let DB = null

function short(id) {
  return id.replace(/^minecraft:/, '')
}

// 'stone', 'minecraft:stone', 'minecraft:oak_stairs[facing=east]', { name } -> 'minecraft:stone'
export function normalizeId(id) {
  const name = typeof id === 'object' && id !== null ? id.name : String(id)
  const bare = name.replace(/\[.*$/, '').trim()
  return bare.includes(':') ? bare : `minecraft:${bare}`
}

function load() {
  if (DB) return DB
  const raw = JSON.parse(fs.readFileSync(DATA_URL, 'utf8'))
  let materials = {}
  try {
    materials = JSON.parse(fs.readFileSync(MATERIALS_URL, 'utf8'))
  } catch {
    materials = {}
  }
  // block id -> { kind, family record }
  const matOf = new Map()
  for (const [key, fam] of Object.entries(materials)) {
    if (key === 'color' || !fam || typeof fam !== 'object') continue
    for (const [field, value] of Object.entries(fam)) {
      if (typeof value !== 'string' || !value.startsWith('minecraft:')) continue
      if (!matOf.has(value) || field === 'block') matOf.set(value, { kind: fam.kind, family: fam, isBlock: field === 'block' })
    }
  }
  const entries = new Map()
  for (const [id, e] of Object.entries(raw)) {
    const n = short(id)
    const { L, C, h } = lch(e.lab)
    const tags = new Set()
    const mat = matOf.get(id)
    if (mat?.kind) tags.add(mat.kind)
    const family = familyOf(e.lab)
    tags.add(family)
    if (e.full) tags.add('full')
    if (e.transparent) tags.add('transparent')
    if (e.emissive) tags.add('emissive')
    if (e.tinted) tags.add('tinted')
    if (e.approx) tags.add('approx')
    if (TECHNICAL.has(n)) tags.add('technical')
    if (FUNCTIONAL.has(n)) tags.add('functional')
    if (CREATIVE.has(n)) tags.add('creative')
    if (TERRAIN.has(n)) tags.add('terrain')
    if (/_ore$/.test(n)) tags.add('ore')
    if (/_glazed_terracotta$/.test(n)) tags.add('glazed')
    else if (/(^|_)terracotta$/.test(n)) tags.add('terracotta')
    if (/^(infested_|waxed_|suspicious_)/.test(n) || n === 'powder_snow') tags.add('alias')
    if (/^(tube|brain|bubble|fire|horn)_coral_block$/.test(n)) tags.add('live_coral')
    if (/_concrete$/.test(n)) tags.add('concrete')
    if (/_concrete_powder$/.test(n)) tags.add('concrete_powder')
    if (/_wool$/.test(n)) tags.add('wool')
    if (/_planks$/.test(n)) tags.add('planks')
    if (/(_log|_wood|_stem|_hyphae)$/.test(n) || n === 'bamboo_block' || n === 'stripped_bamboo_block') tags.add('log')
    if (/(^|_)glass(_pane)?$/.test(n)) tags.add('glass')
    if (/_leaves$/.test(n)) tags.add('leaves')
    if (/_(stairs|slab|wall|fence|fence_gate|button|pressure_plate|door|trapdoor|carpet)$/.test(n)) tags.add('partial')
    if (n === 'sand' || n === 'red_sand' || n === 'gravel' || /_concrete_powder$/.test(n)) tags.add('gravity')
    entries.set(id, Object.freeze({ id, ...e, L, C, h, family, tags: Object.freeze([...tags]), material: mat?.family ?? null }))
  }
  DB = { entries, labCache: new Map(), poolCache: new Map(), dedupeCache: new WeakMap(), dECache: new Map(), rampCache: new Map() }
  return DB
}

function faceLab(entry, face = 'side') {
  if (face === 'side') return entry.lab
  const key = `${entry.id}|${face}`
  const { labCache } = load()
  let lab = labCache.get(key)
  if (!lab) {
    lab = hexToLab(entry[face] ?? entry.side)
    labCache.set(key, lab)
  }
  return lab
}

// Accepts '#rrggbb' / 'rrggbb', a CIELAB triple [L, a, b], a block id or a colorOf() entry.
function toLab(value, face = 'side') {
  if (Array.isArray(value)) return value
  if (value && typeof value === 'object' && value.lab) return faceLab(value, face)
  const s = String(value)
  if (/^#?[0-9a-fA-F]{6}$/.test(s)) return hexToLab(s)
  const entry = colorOf(s)
  if (!entry) throw new Error(`unknown colour or block: ${value}`)
  return faceLab(entry, face)
}

function matcher(spec) {
  if (spec === undefined || spec === null) return () => false
  if (typeof spec === 'function') return (e) => Boolean(spec(e.id, e))
  const list = Array.isArray(spec) ? spec : [spec]
  const tests = list.map((p) => {
    if (p instanceof RegExp) return (e) => p.test(e.id) || p.test(short(e.id))
    const s = normalizeId(p)
    if (s.includes('*')) {
      const re = new RegExp(`^${s.replace(/[.+?^${}()|\\]/g, '\\$&').replace(/\*/g, '.*')}$`)
      return (e) => re.test(e.id)
    }
    return (e) => e.id === s
  })
  return (e) => tests.some((t) => t(e))
}

function hasShapes(entry, shapes) {
  if (!shapes || shapes.length === 0) return true
  const fam = entry.material
  if (!fam || fam.block !== entry.id) return false
  // Own shapes only (b.texture maps stairs/slabs/walls to the material's own variants).
  return shapes.every((shape) => typeof fam[shape] === 'string')
}

// Candidate list for nearest/ramp. `kinds` restricts to blocks carrying any of those tags and
// also opts those tags back in when they are excluded by default; `include` only opts in.
function candidates({ full = true, kinds, include, exclude, require: shapes, excludedTags = DEFAULT_EXCLUDED } = {}) {
  const kindList = kinds ? (Array.isArray(kinds) ? kinds : [kinds]) : null
  const includeList = include ? (Array.isArray(include) ? include : [include]) : []
  const optIn = new Set([...(kindList ?? []), ...includeList])
  const blocked = excludedTags.filter((t) => !optIn.has(t))
  const key = JSON.stringify([full, kindList, blocked, shapes ?? null])
  const { entries, poolCache } = load()
  let pool = poolCache.get(key)
  if (!pool) {
    pool = []
    for (const e of entries.values()) {
      if (full && !e.full) continue
      if (blocked.some((t) => e.tags.includes(t))) continue
      if (kindList && !kindList.some((t) => e.tags.includes(t))) continue
      if (!hasShapes(e, shapes)) continue
      pool.push(e)
    }
    poolCache.set(key, pool)
  }
  if (exclude === undefined) return pool
  const isExcluded = matcher(exclude)
  return pool.filter((e) => !isExcluded(e))
}

// ---------------------------------------------------------------------------------------------
// Public API.
// ---------------------------------------------------------------------------------------------

// Colour entry of a block (state suffix and namespace optional) or null when unknown.
// Fields: side/top/bottom/avg hex, lab, L, C (chroma), h (hue angle), family, noise (busyness),
// full, transparent, emissive, tags, material (materials.json family or null).
export function colorOf(id) {
  return load().entries.get(normalizeId(id)) ?? null
}

// Closest building block(s) by CIEDE2000 to a colour ('#hex', [L, a, b]) or to another block.
// Options: full (default true: full opaque cubes only), face ('side' | 'top' | 'avg'),
// kinds (tags to restrict to, e.g. ['stone'], ['concrete'], ['wood', 'planks'], ['blue']; also
// opts excluded tags like 'ore' or 'glazed' back in), include (opt-in tags without restricting),
// exclude (ids, globs like '*_wool', RegExp or predicate), require (['stairs', 'slab', ...]:
// material must have those shapes), count (> 1 returns an array).
// Returns { id, dE, side, L } (or an array of them), or null when nothing matches.
export function nearest(target, { full = true, face = 'side', kinds, include, exclude, require: shapes, count = 1 } = {}) {
  const lab = toLab(target, face)
  const self = typeof target === 'string' && !/^#?[0-9a-fA-F]{6}$/.test(target) ? normalizeId(target) : null
  const pool = candidates({ full, kinds, include, exclude, require: shapes })
  const scored = []
  for (const e of pool) {
    if (e.id === self) continue
    scored.push({ id: e.id, dE: deltaE(lab, faceLab(e, face)), side: e.side, L: e.L })
  }
  scored.sort((a, b) => a.dE - b.dE || a.id.length - b.id.length || a.id.localeCompare(b.id))
  // Identical-looking duplicates (oak_log/oak_wood) collapse to the shorter id.
  const out = []
  for (const s of scored) {
    if (out.some((o) => o.side === s.side && Math.abs(o.dE - s.dE) < 1e-9)) continue
    out.push({ ...s, dE: Math.round(s.dE * 100) / 100 })
    if (out.length >= count) break
  }
  if (count > 1) return out
  return out[0] ?? null
}

// Smoothest perceptual ladder of `steps` blocks from `fromId` to `toId` (both included).
// Candidates lie near the straight from->to line in CIELAB; lightness moves one way; a dynamic
// program minimises the sum of CIEDE2000 steps raised to a power (evenness) plus a penalty for
// straying from the line. Options:
//   full (default true), kinds / include / exclude / require: as nearest()
//   smoothness (0..1, default 0.5): higher keeps hue closer to the straight line and spaces
//     steps more evenly; lower allows detours through other hues for more even value steps
//   via: ['moss_block'] waypoints the ladder must pass through
//   face: 'side' (default) | 'top' | 'avg'
//   details: true returns { ids, steps: [ΔE00...], L: [...] } instead of the id list
// steps omitted (or 'auto') picks the most even count between 4 and 10. When fewer distinct
// blocks exist between the endpoints, the result can be shorter than `steps`.
export function ramp(fromId, toId, steps = 'auto', opts = {}) {
  const memoKey = typeof opts.exclude === 'function' ? null : JSON.stringify([normalizeId(fromId), normalizeId(toId), steps, { ...opts, exclude: opts.exclude instanceof RegExp ? String(opts.exclude) : opts.exclude }])
  const { rampCache } = load()
  if (memoKey && rampCache.has(memoKey)) {
    const hit = rampCache.get(memoKey)
    return Array.isArray(hit) ? [...hit] : { ids: [...hit.ids], steps: [...hit.steps], L: [...hit.L] }
  }
  const result = rampUncached(fromId, toId, steps, opts)
  if (memoKey) rampCache.set(memoKey, result)
  return Array.isArray(result) ? [...result] : { ids: [...result.ids], steps: [...result.steps], L: [...result.L] }
}

function rampUncached(fromId, toId, steps, opts) {
  const { full = true, kinds, include, exclude, require: shapes, smoothness = 0.5, via = [], face = 'side', details = false } = opts
  const from = colorOf(fromId)
  const to = colorOf(toId)
  if (!from) throw new Error(`ramp: unknown block ${fromId}`)
  if (!to) throw new Error(`ramp: unknown block ${toId}`)
  const waypoints = [from, ...via.map((v) => {
    const e = colorOf(v)
    if (!e) throw new Error(`ramp: unknown via block ${v}`)
    return e
  }), to]
  const pool = dedupe(candidates({ full, kinds, include, exclude, require: shapes, excludedTags: RAMP_EXCLUDED }), face)
  const s = Math.max(0, Math.min(1, smoothness))
  const segs = waypoints.length - 1
  const total = steps === 'auto' || steps === undefined ? null : Math.max(2, Math.floor(steps))
  let chain = [waypoints[0]]
  for (let i = 0; i < segs; i += 1) {
    const A = waypoints[i]
    const B = waypoints[i + 1]
    let edges = null
    if (total !== null) {
      // Share the requested edges between segments in proportion to their colour distance.
      const lens = waypoints.slice(1).map((w, k) => deltaE(faceLab(waypoints[k], face), faceLab(w, face)))
      const sum = lens.reduce((x, y) => x + y, 0) || 1
      const want = total - 1
      const alloc = lens.map((l) => Math.max(1, Math.round((want * l) / sum)))
      let diff = want - alloc.reduce((x, y) => x + y, 0)
      for (let k = 0; diff !== 0 && k < 100; k += 1) {
        const j = k % alloc.length
        if (diff > 0) { alloc[j] += 1; diff -= 1 } else if (alloc[j] > 1) { alloc[j] -= 1; diff += 1 }
      }
      edges = alloc[i]
    }
    const seg = solveSegment(A, B, pool, { edges, s, face, autoRange: [Math.max(1, Math.ceil(3 / segs)), Math.ceil(9 / segs)] })
    chain = chain.concat(seg.slice(1))
  }
  const ids = chain.map((e) => e.id)
  if (!details) return ids
  const labs = chain.map((e) => faceLab(e, face))
  return {
    ids,
    steps: labs.slice(1).map((lab, i) => Math.round(deltaE(labs[i], lab) * 10) / 10),
    L: labs.map((lab) => Math.round(lab[0])),
  }
}

function dedupe(pool, face) {
  const { dedupeCache } = load()
  let byFace = dedupeCache.get(pool)
  if (!byFace) {
    byFace = {}
    dedupeCache.set(pool, byFace)
  }
  if (!byFace[face]) byFace[face] = dedupeUncached(pool, face)
  return byFace[face]
}

// ΔE00 between two entries' faces, cached across calls.
function entryDE(a, b, face) {
  const { dECache } = load()
  const key = a.id < b.id ? `${a.id}|${b.id}|${face}` : `${b.id}|${a.id}|${face}`
  let v = dECache.get(key)
  if (v === undefined) {
    v = deltaE(faceLab(a, face), faceLab(b, face))
    dECache.set(key, v)
  }
  return v
}

function dedupeUncached(pool, face) {
  const sorted = [...pool].sort((a, b) => short(a.id).length - short(b.id).length || a.id.localeCompare(b.id))
  const out = []
  for (const e of sorted) {
    const lab = faceLab(e, face)
    if (!out.some((o) => Math.abs(faceLab(o, face)[0] - lab[0]) < 2 && entryDE(o, e, face) < 1)) out.push(e)
  }
  return out
}

function solveSegment(A, B, pool, { edges, s, face, autoRange }) {
  const la = faceLab(A, face)
  const lb = faceLab(B, face)
  const ab = la.map((v, i) => lb[i] - v)
  const len2 = ab.reduce((t, v) => t + v * v, 0) || 1
  const corridor = Math.max(10, (0.45 - 0.25 * s) * Math.sqrt(len2))
  const nodes = [{ e: A, lab: la, t: 0, d: 0 }]
  for (const e of pool) {
    if (e.id === A.id || e.id === B.id) continue
    const lab = faceLab(e, face)
    const t = lab.reduce((acc, v, i) => acc + (v - la[i]) * ab[i], 0) / len2
    if (t <= 0.03 || t >= 0.97) continue
    let d2 = 0
    for (let i = 0; i < 3; i += 1) d2 += (lab[i] - (la[i] + ab[i] * t)) ** 2
    const d = Math.sqrt(d2)
    if (d > corridor) continue
    nodes.push({ e, lab, t, d })
  }
  nodes.push({ e: B, lab: lb, t: 1, d: 0 })
  nodes.sort((p, q) => p.t - q.t)
  const N = nodes.length
  const power = 2 + 3 * s
  const lambda = 0.1 + 0.8 * s
  const dir = Math.sign(lb[0] - la[0])
  const monotonic = Math.abs(lb[0] - la[0]) >= 10
  const dist = (i, j) => entryDE(nodes[i].e, nodes[j].e, face)
  const [lo, hi] = edges ? [edges, edges] : autoRange
  let prev = new Array(N).fill(Infinity)
  prev[0] = 0
  const back = []
  const results = []
  for (let k = 1; k <= Math.min(Math.max(hi, lo), N - 1); k += 1) {
    const cur = new Array(N).fill(Infinity)
    const bk = new Array(N).fill(-1)
    for (let j = 1; j < N; j += 1) {
      for (let i = 0; i < j; i += 1) {
        if (prev[i] === Infinity || nodes[j].t <= nodes[i].t) continue
        if (monotonic && (nodes[j].lab[0] - nodes[i].lab[0]) * dir < -1) continue
        const c = prev[i] + dist(i, j) ** power + lambda * (nodes[j].d ** power) / 100
        if (c < cur[j]) {
          cur[j] = c
          bk[j] = i
        }
      }
    }
    back.push(bk)
    prev = cur
    if (cur[N - 1] < Infinity) {
      const path = [N - 1]
      for (let kk = k - 1; kk >= 0; kk -= 1) path.unshift(back[kk][path[0]])
      const stepsDE = path.slice(1).map((p, i) => dist(path[i], p))
      const min = Math.min(...stepsDE)
      const max = Math.max(...stepsDE)
      results.push({ k, path, score: 2 * max - min + (min < 3 ? 3 * (3 - min) + 4 : 0) })
    }
  }
  if (results.length === 0) return [A, B]
  let pick
  if (edges) {
    // Exact count when possible, otherwise the longest chain that exists.
    pick = results.find((r) => r.k === edges) ?? results[results.length - 1]
  } else {
    const inRange = results.filter((r) => r.k >= lo)
    const pool = inRange.length ? inRange : results
    const best = Math.min(...pool.map((r) => r.score))
    pick = pool.filter((r) => r.score <= best + 0.5).pop()
  }
  return pick.path.map((i) => nodes[i].e)
}

// Ids sorted by L* of the chosen face, lightest first (pass { lightestFirst: false } for dark
// first). Unknown ids sort last.
export function sortByLightness(ids, { face = 'side', lightestFirst = true } = {}) {
  const L = (id) => {
    const e = colorOf(id)
    return e ? faceLab(e, face)[0] : -Infinity
  }
  return [...ids].sort((a, b) => (lightestFirst ? L(b) - L(a) : L(a) - L(b)))
}

// Value and colour difference of two blocks or colours.
// Returns { dL (a minus b, signed), absL, dE, reads } where reads is
// 'same' (dE < 3), 'texture-mix' (< 6), 'subtle' (< 12 and |dL| < 15), 'distinct', or 'strong' (|dL| >= 30).
export function contrast(a, b, { face = 'side', faceB } = {}) {
  const la = toLab(a, face)
  const lb = toLab(b, faceB ?? face)
  const dL = la[0] - lb[0]
  const dE = deltaE(la, lb)
  const absL = Math.abs(dL)
  const reads = dE < 3 ? 'same' : dE < 6 ? 'texture-mix' : absL >= 30 ? 'strong' : dE < 12 && absL < 15 ? 'subtle' : 'distinct'
  return { dL: Math.round(dL * 10) / 10, absL: Math.round(absL * 10) / 10, dE: Math.round(dE * 10) / 10, reads }
}

// Role targets (|ΔL*| minimum) used by paletteReport when roles are given.
export const ROLE_TARGETS = [
  { a: 'wall', b: 'roof', minL: 15, why: 'roof and wall should separate by value' },
  { a: 'wall', b: 'frame', minL: 12, why: 'frame/trim should read against the wall' },
  { a: 'wall', b: 'trim', minL: 12, why: 'trim should read against the wall' },
  { a: 'wall', b: 'foundation', minL: 8, why: 'foundation should read as a separate base' },
  { a: 'wall', b: 'accent', minE: 15, why: 'accent should stand out from the wall' },
  { a: 'roof', b: 'frame', minE: 6, why: 'roof and frame should not merge' },
]

// Checks a palette. `ids` is a list of blocks, or an object of role -> block (or list of blocks
// for a mixed surface; the mix is evaluated by its average Lab). Returns
// { blocks: [...], value: { min, max, spread }, hue: { spread, families, chromatic }, busy: [...],
//   pairs: [{ a, b, dE, dL }], warnings: [...], notes: [...], ok } (ok = no warnings; notes are
//   informational: light sources, gravity blocks, glazed patterns).
export function paletteReport(ids, { minPairDE = 5, busyAt = 0.08 } = {}) {
  const roles = Array.isArray(ids) ? null : ids
  const items = []
  const warnings = []
  const list = roles ? Object.entries(roles) : ids.map((id) => [null, id])
  for (const [role, value] of list) {
    const members = Array.isArray(value) ? value : [value]
    const es = members.map((m) => ({ m, e: colorOf(m) }))
    const unknown = es.filter((x) => !x.e).map((x) => x.m)
    if (unknown.length) {
      warnings.push(`unknown block id: ${unknown.join(', ')}`)
      continue
    }
    const labs = es.map((x) => x.e.lab)
    const lab = [0, 1, 2].map((i) => labs.reduce((t, l) => t + l[i], 0) / labs.length)
    const { L, C, h } = lch(lab)
    items.push({
      role,
      ids: es.map((x) => x.e.id),
      id: es.map((x) => short(x.e.id)).join('+'),
      lab,
      L: Math.round(L),
      C: Math.round(C),
      h: Math.round(h),
      family: familyOf(lab),
      noise: Math.max(...es.map((x) => x.e.noise)),
      tags: [...new Set(es.flatMap((x) => x.e.tags))],
    })
  }
  const allIds = items.flatMap((i) => i.ids)
  const distinct = new Set(allIds)
  if (distinct.size > 6) warnings.push(`${distinct.size} distinct blocks: more than 6 usually reads as noise; merge or drop some`)
  if (items.length && distinct.size < 3) warnings.push(`only ${distinct.size} block(s): add a darker base or a trim for structure`)
  const Ls = items.map((i) => i.L)
  const value = { min: Math.min(...Ls), max: Math.max(...Ls), spread: Math.max(...Ls) - Math.min(...Ls) }
  if (items.length >= 2 && value.spread < 25) warnings.push(`value spread is only ${value.spread} L*: add a clearly lighter or darker element (aim for 35+)`)
  // Pairwise similarity (different roles, or plain list).
  const pairs = []
  for (let i = 0; i < items.length; i += 1) {
    for (let j = i + 1; j < items.length; j += 1) {
      const A = items[i]
      const B = items[j]
      const dE = deltaE(A.lab, B.lab)
      const dL = A.L - B.L
      pairs.push({ a: A.role ?? A.id, b: B.role ?? B.id, dE: Math.round(dE * 10) / 10, dL })
      if (dE < minPairDE) {
        warnings.push(`${A.role ? `${A.role} (${A.id})` : A.id} and ${B.role ? `${B.role} (${B.id})` : B.id} are too similar to read apart at distance (ΔE00 ${dE.toFixed(1)}); fine only as a texture mix inside one surface`)
      }
    }
  }
  // Role value targets.
  if (roles) {
    const byRole = new Map(items.map((i) => [i.role, i]))
    for (const t of ROLE_TARGETS) {
      const A = byRole.get(t.a)
      const B = byRole.get(t.b)
      if (!A || !B) continue
      const dE = deltaE(A.lab, B.lab)
      if (t.minL && Math.abs(A.L - B.L) < t.minL) warnings.push(`${t.a} L*${A.L} vs ${t.b} L*${B.L}: |ΔL*| ${Math.abs(A.L - B.L)} < ${t.minL} (${t.why})`)
      if (t.minE && dE < t.minE) warnings.push(`${t.a} vs ${t.b}: ΔE00 ${dE.toFixed(1)} < ${t.minE} (${t.why})`)
    }
    const wall = byRole.get('wall')
    const base = byRole.get('foundation') ?? byRole.get('base')
    if (wall && base && base.L > wall.L + 3) warnings.push(`foundation (L*${base.L}) is lighter than the wall (L*${wall.L}): a darker base usually anchors a build (convention)`)
  }
  // Hue structure.
  const chromatic = items.filter((i) => i.C >= 20)
  const hueDiff = (a, b) => {
    const d = Math.abs(a - b) % 360
    return d > 180 ? 360 - d : d
  }
  let hueSpread = 0
  for (const a of chromatic) for (const b of chromatic) hueSpread = Math.max(hueSpread, hueDiff(a.h, b.h))
  const hueGroups = []
  for (const c of [...chromatic].sort((a, b) => b.C - a.C)) {
    if (!hueGroups.some((g) => hueDiff(g.h, c.h) <= 40)) hueGroups.push(c)
  }
  if (hueGroups.length > 2) warnings.push(`${hueGroups.length} saturated hue groups (${hueGroups.map((g) => g.id).join(', ')}): keep one base hue family plus at most one contrasting accent`)
  for (let i = 0; i < chromatic.length; i += 1) {
    for (let j = i + 1; j < chromatic.length; j += 1) {
      const A = chromatic[i]
      const B = chromatic[j]
      const d = hueDiff(A.h, B.h)
      if (A.C >= 30 && B.C >= 30 && d > 70 && d < 150 && Math.abs(A.L - B.L) < 20) {
        warnings.push(`hue clash: ${A.id} and ${B.id} are both saturated, ${Math.round(d)}° apart at similar value; desaturate one or separate their values`)
      }
    }
  }
  // Texture busyness.
  const busy = items.filter((i) => i.noise >= busyAt)
  if (busy.length >= 2) warnings.push(`${busy.length} busy textures (${busy.map((b) => b.id).join(', ')}): keep one busy surface and make the rest calm`)
  const notes = []
  for (const i of items) {
    if (i.tags.includes('emissive')) notes.push(`${i.id} emits light`)
    if (i.tags.includes('glazed')) notes.push(`${i.id} is patterned (glazed terracotta)`)
    if (i.tags.includes('gravity')) notes.push(`${i.id} falls if unsupported`)
    if (i.tags.includes('live_coral')) warnings.push(`${i.id} turns grey without water`)
  }
  return {
    blocks: items.map(({ role, id, L, C, h, family, noise }) => ({ role, id, L, C, h, family, noise })),
    value,
    hue: { spread: Math.round(hueSpread), families: [...new Set(items.map((i) => i.family))], chromatic: chromatic.length },
    busy: busy.map((b) => b.id),
    pairs,
    warnings,
    notes,
    ok: warnings.length === 0,
  }
}
